import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
export const DATA_DIR = path.resolve(__dirname, 'data');

const fileMetadataTool = {
  name: 'file_metadata',
  description:
    'Return metadata for a file inside the workspace data directory: relative path, byte size, and lowercase extension. Does not expose file contents.',
  inputSchema: {
    type: 'object',
    properties: {
      path: {
        type: 'string',
        description:
          'Path to the file, relative to the data directory (e.g. "readme.txt" or "sub/file.txt").'
      }
    },
    required: ['path'],
    additionalProperties: false
  }
};

export async function listTools() {
  return [fileMetadataTool];
}

export async function callTool(name, args) {
  if (name === 'file_metadata') {
    return getFileMetadata(args);
  }
  throw new Error(`Unknown tool: ${name}`);
}

async function getFileMetadata(args) {
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('arguments must be a JSON object');
  }

  const knownKeys = new Set(['path']);
  const unexpected = Object.keys(args).filter((k) => !knownKeys.has(k));
  if (unexpected.length > 0) {
    throw new Error(
      `unexpected argument(s): ${unexpected.join(', ')} (only "path" is accepted)`
    );
  }

  const { path: rawPath } = args;
  if (typeof rawPath !== 'string') {
    throw new Error('path must be a string');
  }
  if (rawPath.length === 0) {
    throw new Error('path must be a non-empty string');
  }
  if (path.isAbsolute(rawPath)) {
    throw new Error('path must be relative to the data directory');
  }

  // Resolve the requested path against DATA_DIR, then verify it stays
  // inside DATA_DIR even after symlink resolution. This blocks traversal
  // attempts using "..", absolute paths, or symlinks pointing outside.
  const requested = path.resolve(DATA_DIR, rawPath);

  let realTarget;
  try {
    realTarget = await fs.realpath(requested);
  } catch (err) {
    if (err.code === 'ENOENT') {
      throw new Error(`file not found: ${rawPath}`);
    }
    throw err;
  }

  const realRel = path.relative(DATA_DIR, realTarget);
  if (
    realRel === '' ||
    realRel.startsWith('..') ||
    path.isAbsolute(realRel)
  ) {
    throw new Error(
      `path traversal outside the data directory is not allowed: ${rawPath}`
    );
  }

  const stat = await fs.stat(realTarget);
  if (!stat.isFile()) {
    throw new Error(`not a regular file: ${rawPath}`);
  }

  const ext = path.extname(realTarget).toLowerCase(); // e.g. ".txt" or ""
  const relativePath = realRel.split(path.sep).join('/');

  const text = [
    `path: ${relativePath}`,
    `size: ${stat.size} bytes`,
    `extension: ${ext || '(none)'}`
  ].join('\n');

  return {
    content: [{ type: 'text', text }]
  };
}

